// Trigger reading of DB50_KPIs.ProductionCount
// Define all DB50_KPIs variables and their corresponding OPC-UA data types
var kpis = [
    { name: "ProductionCount", type: "Int32" },   // DInt
    { name: "LoadedPalletCount", type: "Int16" }, // Int
    { name: "SortedCount", type: "Int32" },       // DInt
    { name: "SortRate", type: "Float" },          // Real
    { name: "CycleTime", type: "Float" },         // Real
    { name: "Throughput", type: "Float" },        // Real
    { name: "Availability", type: "Float" },      // Real
    { name: "Performance", type: "Float" },       // Real
    { name: "Yield", type: "Float" },             // Real
    { name: "OEE", type: "Float" },               // Real
    { name: "ActiveAlarms", type: "Int16" },      // Int
    { name: "Downtime", type: "Int32" },          // DInt
    { name: "Status", type: "UInt16" }            // Word
];

var msgs = [];

// Loop through the list and create a separate message object for each KPI
for (var i = 0; i < kpis.length; i++) {
    msgs.push({
        topic: 'ns=3;s="DB50_KPIs"."' + kpis[i].name + '"',
        datatype: kpis[i].type,
        kpiName: kpis[i].name // Pass the custom name forward to the next node
    });
}

// Returning an array wrapped in an array sends them as individual sequential messages
return [msgs];

// Retrieve the value and the custom kpiName passed from the first node
var value = msg.payload;
var kpiName = msg.kpiName; 

// Dynamically set the MQTT topic (e.g., SmartLine360/OEE or SmartLine360/Throughput)
msg.topic = "SmartLine360/" + kpiName;

// Build the standard IIoT JSON payload
msg.payload = {
    timestamp: new Date().toISOString(),
    station: "Line_Overall",
    metric: kpiName,
    value: Number(value)
};

return msg;
